import sys; sys.path.insert(0, __import__("os").path.join(__import__("os").path.dirname(__file__), "..", "..", "pipeline"))
from scriptkit import sc, ch, save, S

# Grandma Ruth 101 · Christmas recipe: soft homemade dinner rolls (Parker House style)

sc("""Sweetheart, at every Christmas dinner I've ever been to, the first thing to disappear isn't the ham or the turkey. It's the rolls. Soft, buttery, golden homemade dinner rolls that pull apart in your fingers. But most people are scared of yeast, so they buy a bag of rolls from the store that taste like cardboard, or they try homemade, and they come out hard, flat, and dense as hockey pucks.""",
   "basket of soft golden dinner rolls", "FIRST TO DISAPPEAR")
sc("""So tonight I'm giving you my mother's Christmas dinner rolls, step by step, the soft, buttery folded kind they used to call Parker House rolls. And the five mistakes that make yeast rolls hard. Stay with me, because the last secret is something my mother did with a pastry brush in the last minute, and it's why her rolls were famous at First Methodist for forty years.""",
   "folded Parker House rolls in pan", "FAMOUS FOR FORTY YEARS")

ch("Mother's rolls")
sc("""My mother made rolls every Saturday of her life, honey, and three dozen extra at Christmas. She'd start the dough right after breakfast, and the whole house would smell like warm yeast and butter by lunch. Danny and I would hang around the kitchen like hungry puppies. She'd let us each have one hot roll from the first pan, with butter melting into it. That was worth the wait for the whole week.""",
   "1950s mother kneading dough kitchen", "ONE HOT ROLL EACH")
sc("""These rolls are named after the Parker House Hotel in Boston, where a baker invented them in the eighteen seventies. The story goes that he was in a bad mood one night and threw half-finished rolls into the oven, and they came out folded and perfect. I don't know if that's true, honey, but I like it. In a minute I'll tell you the one temperature mistake that kills more yeast rolls than anything.""",
   "historic Boston hotel 1870s", "THE PARKER HOUSE")
sc("""People think yeast is hard. It isn't, sweetheart. Yeast is just alive, like a little pet. It wants to be warm, not hot. It wants a little sugar to eat. And it wants time. If you give it those three things, it will do all the work for you. My mother never measured the temperature in her life. She tested the milk on her wrist, like a baby's bottle.""",
   "testing warm milk on wrist", "YEAST IS ALIVE")

ch("What you need")
sc("""Here's what you need for about two dozen rolls. One cup of whole milk. Half a cup of butter, plus more for brushing. A quarter cup of sugar. One packet of active dry yeast, which is two and a quarter teaspoons. A quarter cup of warm water. Two eggs. One and a half teaspoons of salt. And about four cups of all-purpose flour. That's all. Things you probably have right now.""",
   "flour milk butter eggs yeast packet", "THE INGREDIENTS")
sc("""And here's mistake number one. Killing the yeast. Heat the milk and butter together just until the butter melts, then let it cool until it's warm, like bathwater. About a hundred and ten degrees. If it's too hot to hold your finger in comfortably, it's too hot for yeast. Hot milk kills the yeast, and your rolls never rise. That's the temperature mistake I promised you.""",
   "testing milk temperature with finger", "WARM LIKE BATHWATER")
sc("""Stir the yeast and a pinch of the sugar into the quarter cup of warm water and let it sit for five minutes. It should get foamy and smell like bread. That's how you know it's alive. If it just sits there flat, your yeast is old, sweetheart. Throw it out and buy a new packet. Better to lose a packet of yeast than a whole morning and four cups of flour.""",
   "foamy yeast in bowl of water", "IT SHOULD FOAM")

ch("The dough")
sc("""In a big bowl, mix the warm milk and butter, the rest of the sugar, the salt, the eggs, and the foamy yeast. Then add the flour one cup at a time, stirring with a wooden spoon, until you have a soft, shaggy dough that pulls away from the bowl. And here's mistake number two. Adding too much flour. Soft, slightly sticky dough makes soft rolls. Stiff dough makes hard ones.""",
   "shaggy soft dough in mixing bowl", "SOFT AND A LITTLE STICKY")
sc("""If this is helping you, tap the like button for me, sweetheart. It helps Grandma more than you know. Turn the dough out on a lightly floured counter and knead it for about eight minutes. Push it away with the heel of your hand, fold it back, turn it, and push again. When it's ready, it'll be smooth and springy, like a baby's cheek. Poke it, and it should slowly bounce back.""",
   "kneading dough on floured counter", "LIKE A BABY'S CHEEK")
sc("""And mistake number three. Not kneading long enough. Kneading builds up the stretch in the dough, which traps the little air bubbles the yeast makes. Five minutes isn't enough. Set a timer for eight. It's good exercise, honey. My mother said kneading bread was cheaper than a psychiatrist, and she was right. Whatever's bothering you, punch it into the dough.""",
   "hands kneading dough timer on counter", "CHEAPER THAN A PSYCHIATRIST")

ch("The rise")
sc("""Put the dough in a buttered bowl, turn it over once so the top is buttered, and cover it with a clean dish towel. Let it rise somewhere warm until it's doubled in size, about an hour to an hour and a half. And mistake number four is rushing it, or putting it somewhere cold. A drafty kitchen in December can take three hours. Be patient. The rise is where the flavor comes from.""",
   "dough rising in bowl under dish towel", "LET IT DOUBLE")
sc("""Here's my mother's trick for a cold kitchen, sweetheart. Turn your oven on to the lowest setting for just two minutes, then turn it off. Put the bowl in the oven with the light on and the door closed. It's the perfect warm, draft-free spot. Just remember to take the bowl out before you preheat for baking. I melted a plastic bowl once, in nineteen seventy-nine. Harold still teased me about it.""",
   "bowl of dough inside oven with light on", "THE OVEN LIGHT TRICK")

sc("""How do you know it's doubled, honey? Here's the finger test. Flour your finger and poke it gently into the dough, about half an inch. If the hole stays there, it's ready. If it springs right back and fills in, it needs more time. If the whole dough sighs and collapses, it went too long, but don't worry, just punch it down, shape it, and it'll still be fine.""",
   "finger poking risen dough test", "THE FINGER TEST")
ch("Shaping")
sc("""So far, warm milk, soft dough, eight minutes of kneading, and a good rise. Punch the dough down gently and roll it out on the counter about half an inch thick. Cut it into circles with a biscuit cutter or a glass. Brush each circle with melted butter. Then press the back of a butter knife across the middle, off-center, and fold each one over, like a little pocketbook.""",
   "folding dough circles into pocketbook shapes", "LIKE A LITTLE POCKETBOOK")
sc("""Line them up in a buttered nine by thirteen pan, close together, so they're just touching. That's important, honey. Rolls baked touching each other stay soft on the sides. Rolls baked apart get crusty all over. Cover them again with the towel and let them rise a second time, about forty-five minutes, until they're puffy and filling up the pan.""",
   "rolls lined up touching in baking pan", "CLOSE TOGETHER")
sc("""And you can make them ahead for Christmas, sweetheart. After shaping, cover the pan with plastic wrap and put it in the icebox overnight. On Christmas Day, take it out three hours before dinner and let it come to room temperature and finish rising. Then bake. They're just as good, and the morning of Christmas is so much calmer.""",
   "covered pan of rolls in refrigerator", "MAKE THEM THE NIGHT BEFORE")

ch("The secret")
sc("""Bake at three hundred seventy-five for about fifteen to eighteen minutes, until they're deep golden brown on top. Mistake number five is underbaking. Pale rolls taste raw and doughy in the middle. You want real color, the color of a good paper bag. Now, the secret I promised you. The second they come out of the oven, brush the tops with melted butter. Generously.""",
   "brushing melted butter on hot rolls", "THE SECOND THEY COME OUT")
sc("""And then, my mother's last-minute trick. Sprinkle a few flakes of coarse salt over the buttery tops. Just a pinch. The salt against the sweet butter makes people close their eyes when they take a bite. Then cover the pan with a towel for five minutes, so the steam keeps them soft. The ladies at First Methodist begged her for that recipe for forty years. She never told them about the salt.""",
   "coarse salt on buttered rolls", "A PINCH OF SALT")

sc("""And don't throw out the leftovers, sweetheart. Day-old rolls make the best little ham sandwiches on December twenty-sixth, split and toasted, with a smear of mustard. Or tear them up for bread pudding, or for the stuffing next Thanksgiving. They freeze beautifully for three months, too. Warm them wrapped in foil at three fifty for ten minutes and they taste fresh-baked. My mother never wasted one roll in her life.""",
   "small ham sandwiches on dinner rolls", "LITTLE HAM SANDWICHES")
ch("Grandma's kitchen")
sc("""So one more time. Warm milk, not hot. Proof your yeast until it foams. Keep the dough soft. Knead for eight minutes. Let it double somewhere warm. Fold them like pocketbooks and bake them touching. Golden brown, not pale. And melted butter and a pinch of salt the second they come out. Those are the rolls everybody at your Christmas table will remember.""",
   "basket of rolls on Christmas table", "THE ROLLS THEY REMEMBER")
sc("""Tell me in the comments, sweetheart. Are you scared of yeast, or are you a bread baker? Be honest with Grandma. The whole playlist of Grandma's recipes is right there on your screen, and I'll see you in the next video. Good night, honey. Merry Christmas.""",
   "warm kitchen evening fresh bread", "SCARED OF YEAST?")

for s in S:
    s["cuts"], s["moves"] = 4, True

save("grandma101", "Dinner Rolls EVERYONE's Grandma Made at Christmas (Why Yours Are HARD)",
     ["Grandma Ruth is a narrated character built from real memories and records of the era.",
      "Parker House rolls are named for the Parker House Hotel in Boston, where they were created in the 1870s.",
      "Recipe as written by Grandma Ruth: 1 cup whole milk, 1/2 cup butter, 1/4 cup sugar, 1 packet active dry yeast, 1/4 cup warm water, 2 eggs, 1 1/2 tsp salt, about 4 cups flour; kneaded 8 minutes, two rises; 375F for 15-18 minutes, brushed with butter and flaky salt."],
     "christmas recipe", minutes=(10, 14.5), voice="en_US-lessac-high")
